[{"query":"query AccommodationIkyu($accommodationId: AccommodationIdScalar!, $device: Device!, $accommodationStoriesFirst: Int!, $accommodationRestaurantFirst: Int!, $topicsType: GuideEnum!, $pickupReviewFirst: Int!, $preview: Boolean! = false, $reviewImagesFirst: Int! = 1, $skipReviewImages: Boolean! = true, $skipMemberHashSha1: Boolean! = false, $accommodationAmountInput: AccommodationAmountInput!, $includeFurusato: Boolean!) {
  accommodation(accommodationId: $accommodationId) {
    chatQuestions
    premium
    premiumBenefits {
      __typename
    }
    furusato2 {
      __typename
    }
    ...BreadcrumbAccommodation
    ...BreadcrumbAccommodationTheme
    ...AccommodationFurusatoHeaderBannerAccommodation
    ...AccommodationFurusatoMiddleBannerAccommodation
    ...AccommodationAnnouncementsAccommodation
    ...AccommodationAvailableRoomTimeAccommodation
    ...AccommodationDescriptionAccommodation
    ...AccommodationExclusiveBenefitAccommodation
    ...FurusatoLabelAccommodation
    ...AccommodationFavoriteAccommodation
    ...AccommodationHeroboxAccommodationAllowInstantDiscount
    ...AIChatAccommodation
    ...AccommodationIntroductionAccommodation
    ...AccommodationFacilityServiceAccommodation
    ...AccommodationListSurroundingAreaSearchCTAAccommodation
    ...AccommodationLowestAmountAccommodationAllowInstantDiscount
    ...AccommodationNotesAccommodation
    ...AccommodationOtoriyoseAccommodation
    ...AccommodationPhotogalleryHeadlineAccommodation
    ...AccommodationRatingAccommodation
    ...AccommodationRestaurantsAccommodation
    ...RelatedGroupHotelListAccommodation
    ...StoryLinkListAccommodation
    ...ThemeListAccommodation
  }
}

fragment FurusatoDonationImageAmountAccommodation on Accommodation {
