    discountLimited
    governments {
      id
      status
      gifts {
        id
        donationPrice
        discountPrice
      }
    }
  }
}

fragment FurusatoDonationImageLabelsAccommodation on Accommodation {
  furusato2 @include(if: $includeFurusato) {
