}","variables":{"accommodationId":"00002889","device":"PC","accommodationStoriesFirst":5,"accommodationRestaurantFirst":10,"preview":false,"topicsType":"ACCOMMODATION","searchRoomsInput":{"checkInDate":"2026-11-17","discount":true,"lodgingCount":1,"peopleCount":2,"roomAttributes":["18"],"roomCount":1,"searchType":"1","sortItem":"1","sortOrder":"1","preferHighAmount":false,"currency":"JPY","preferHighPoint":false,"sortAmountTarget":"USE","preferBookable":true},"searchRoomsFirst":1,"roomAmountInput":{"checkInDate":"2026-11-17","discount":true,"lodgingCount":1,"peopleCount":2,"roomAttributes":["18"],"roomCount":1,"searchType":"1","sortItem":"35","sortOrder":"1","currency":"JPY","sortAmountTarget":"USE"},"roomAmountInputFirst":1,"needRooms":true,"maximumPointsForLowestPriceRoomSpecified":false,"highestPointAmountInput":{"checkInDate":"2026-11-17","discount":true,"lodgingCount":1,"peopleCount":2,"roomAttributes":["18"],"roomCount":1,"searchType":"1","sortItem":"35","sortOrder":"2","currency":"JPY","sortAmountTarget":"USE"},"accommodationAmountInput":{"checkInDate":"2026-11-17","discount":true,"lodgingCount":1,"peopleCount":2,"roomAttributes":["18"],"roomCount":1,"searchType":"1","sortItem":"1","sortOrder":"1","currency":"JPY","sortAmountTarget":"USE"},"includeFurusato":true},"operationName":"AccommodationIkyu"},{"query":"query PlansAndRooms($accommodationId: AccommodationIdScalar!, $accommodationAmountInput: AccommodationAmountInput!, $themeAccommodationAmountInput: AccommodationAmountInput!, $hasCheckInDate: Boolean! = false, $onPlans: Boolean! = false, $plansInput: SearchPlansInput! = {}, $plansFirst: Int! = 3, $plansOffset: Int! = 0, $planAmountsInput: PlanAmountInput! = {sortItem: "1", sortOrder: "1"}, $onRooms: Boolean! = false, $roomsInput: SearchRoomsInput! = {}, $roomsFirst: Int! = 3, $roomsOffset: Int! = 0, $roomAmountsInput: RoomAmountInput! = {sortItem: "1", sortOrder: "1"}, $highestPointRoomAmountInput: RoomAmountInput!, $amountsAndPlanFirst: Int! = 1, $amountsAndRoomFirst: Int! = 1, $currency: Currency!, $isInternationalSite: Boolean!) {
  accommodation(accommodationId: $accommodationId) {
    __typename
    accommodationId
    allowInstantDiscount
    ...PlanListAccommodationAllowInstantDiscount
    ...RoomListAccommodationAllowInstantDiscount
    ...AccommodationLowestAmountAccommodation
    ...AccommodationHeroboxAccommodationLowestAmount
    ...AccommodationHeroboxAccommodationDisappearingInventory @include(if: $hasCheckInDate)
    ...AccommodationThemeListAccommodationRecommend
    searchPlans2(input: $plansInput, first: $plansFirst, offset: $plansOffset) {
      facet @include(if: $onPlans) {
        ...AccommodationAvailabilityCalendarSearchPlansFacet
        ...PlanAndRoomFilterSearchPlansFacet
      }
      plans {
        ...PlanListPlanConnectionAccommodation @include(if: $onPlans)
        ...RoomPlanMetaPlanConnection @include(if: $onPlans)
        ...PlanOrRoomChoicePlanConnection
      }
    }
    searchRooms2(input: $roomsInput, first: $roomsFirst, offset: $roomsOffset) {
      facet @include(if: $onRooms) {
        ...AccommodationAvailabilityCalendarSearchRoomsFacet
        ...PlanAndRoomFilterSearchRoomsFacet
      }
      rooms {
        ...AccommodationFaqListRoomConnection @include(if: $onRooms)
        ...RoomListRoomConnectionAccommodation @include(if: $onRooms)
        ...RoomPlanMetaRoomConnection @include(if: $onRooms)
        ...PlanOrRoomChoiceRoomConnection
      }
    }
  }
}

